use toolboks_addon_sdk::TutorialStep as S;
pub(super) fn system() -> Vec<S> {
    let entries = [
        ("0/0", "memory-summary", "Memory Cleaner · your memory", "In use is RAM currently occupied; Available is what Windows can offer applications. Cached memory is reusable, so a high used percentage alone does not mean anything is wrong."),
        ("0/0", "memory-optimize", "Optimize memory", "This asks applications to release working-set pages they are not actively using. Windows already manages memory, so the benefit may be temporary and applications may briefly slow down. The tour never presses this button."),
        ("0/0", "memory-commit", "Commit · promised memory", "Commit compares memory Windows has promised with its limit, which includes RAM and paging capacity. Approaching that limit is more useful evidence of pressure than a large cache."),
        ("0/0", "memory-apps", "Where your memory goes", "The breakdown groups application memory so you can see the largest users. Windows and other accounts for memory outside the named app groups. Read the last-run report after cleaning to assess the actual result."),
        ("0/0", "memory-options", "Automatic cleaning and exclusions", "Automatic cleaning is optional and off by default. The threshold controls when it can run; Skip apps under N MB avoids disturbing smaller applications. Deeper cache cleaning needs administrator permission. The tour leaves all these settings alone."),
        ("0/0", "memory-options", "Last run and history", "After an optimization, this area explains what changed and keeps session history. Compare the settled result with the before reading; a momentary drop does not necessarily improve performance."),
        ("0/1/selected", "memory-lists", "Advanced · memory lists", "The memory lists show how RAM is divided between active use, standby cache, modified pages and free memory. Standby memory is useful cached data that Windows can reclaim."),
        ("0/1/selected", "toolbar", "Find and group applications", "Search narrows the process table. Grouping combines processes with the same name. Sorting helps find large working sets or private allocations; it does not change the running applications."),
        ("0/1/selected", "table", "Select processes and lock exclusions", "The table compares working-set and private memory. Select rows to inspect or trim them, and lock an application to exclude it. Trimming moves pages out of RAM; it does not close the application."),
        ("0/1/selected", "inspector", "Selected · process actions", "This inspector explains the selected processes and offers Trim selected. Protected or excluded processes can be skipped. Review the result rather than assuming every requested process was changed."),
        ("0/1/system", "inspector", "System · deeper operations", "The System tab exposes system memory-list operations. Some require administrator rights and can remove useful cache. The tour only opens the tab; it does not request permission or perform a clean."),
        ("0/1/rules", "inspector", "Rules · automatic behavior", "Rules controls automatic cleanup and lists excluded applications. These controls affect background behavior, so choose them deliberately. Opening this walkthrough does not turn any rule on."),
        ("1/0", "resource-range", "Resource Monitor · time range", "Choose how much recorded history each graph shows. CPU rated power is an input for an estimate, not a measured processor wattage. The monitor keeps collecting while other tools are open."),
        ("1/0", "graph-cpu", "CPU · load and speed", "CPU usage shows how busy the processor is, and the graph shows how that changes over time. Speed and core counts provide context. A short spike is often normal; sustained load is more useful to investigate."),
        ("1/0", "graph-gpu", "GPU · graphics activity", "This graph shows activity reported by the graphics adapter. Availability depends on hardware and drivers; a missing reading is not proof that the GPU is idle or faulty."),
        ("1/0", "graph-memory", "Memory · RAM pressure", "Memory usage shows occupied physical RAM over time. Compare this with what you are running and the Memory Cleaner commit reading before treating high usage as a problem."),
        ("1/0", "graph-disk", "Disk · reads and writes", "Read and write rates show data moving to and from storage. Active time, when available, shows how busy the disk is. High activity can come from updates, copying files or paging."),
        ("1/0", "graph-network", "Network · upload and download", "The network graph compares incoming and outgoing transfer rates. It shows traffic reported by the system, not the speed your internet subscription promises."),
        ("1/0", "graph-power", "Power · estimates and readings", "Power combines supported measurements and estimates. CPU estimates depend on the rated-power input; GPU readings depend on driver support. These are not a measurement of power at the wall."),
        ("1/0/cpu", "top-processes", "Top processes · CPU", "This ranking identifies the largest current CPU users. It is a live snapshot rather than an all-time total. Multiple processes belonging to the same application may be grouped."),
        ("1/0/memory", "top-processes", "Top processes · Memory", "The Memory ranking highlights applications occupying the most RAM. It helps connect the system-wide memory graph to individual applications."),
        ("1/0/gpu", "top-processes", "Top processes · GPU", "The GPU ranking shows process activity when the hardware exposes it. Missing per-process readings can be a reporting limitation."),
        ("1/0/disk", "top-processes", "Top processes · Disk", "Disk ranking highlights applications moving the most data. A high transfer rate can be expected during installs, downloads or file copies."),
        ("1/1", "details-cpu", "Details · individual CPU cores", "Per-core histories help reveal work concentrated on a few threads. A program can be limited by one busy core even while the total CPU percentage looks modest."),
        ("1/1", "details-gpu", "Details · GPU engines", "Separate engines show 3D, copying, video decoding, encoding or compute work when supported. Different tasks stress different engines, so inspect the engine relevant to what you are doing."),
        ("1/1", "graph-power", "Details · power", "The same power history is available alongside the detailed hardware breakdowns. Treat estimates as context and compare trends over time."),
        ("1/1", "details-disk", "Details · each drive", "Per-drive graphs separate storage activity and capacity readings. This helps distinguish a busy system drive from another disk that is mostly idle."),
        ("1/1", "details-network", "Details · each network adapter", "Adapter histories separate Wi-Fi, Ethernet and other reported interfaces. Virtual adapters can appear too, so use the adapter name to understand the connection."),
        ("1/2", "toolbar", "Processes · search, grouping and pause", "Use the toolbar to filter applications, group related names, or pause the displayed snapshot for inspection. Pausing the display does not suspend applications."),
        ("1/2", "table", "Processes · sort and select", "Sort columns to find large CPU or memory users and select a row to inspect it. A process ID identifies a particular running instance; grouped entries can represent several processes."),
        ("1/2", "inspector", "Processes · actions and protection", "The inspector provides information and available actions for selected processes. Ending a process can lose unsaved work; protection and confirmation checks apply. No process action runs during the tour."),
        ("1/3", "toolbar", "Connections · filters and snapshot", "Filter the connection list by application or address, and use quick filters to narrow the view. Pause freezes the displayed snapshot while applications continue running."),
        ("1/3", "table", "Connections · addresses and states", "Rows show protocol, local and remote endpoints, owning process and connection state. Listening sockets and active connections have different meanings; a connection alone does not establish whether an app is trustworthy."),
        ("1/3", "inspector", "Connections · inspect an endpoint", "Select a connection for process and address details. Copy actions put text on the clipboard. Resolve host name makes a network lookup only when you request it. Ending the owner process can interrupt the application."),
        ("2/0", "table", "Debloater · privacy and advertising", "These entries describe optional Windows changes. Read what each change does, review its current state, and select only what you want. Recommendations are not applied automatically."),
        ("2/0", "inspector", "Review and apply a change", "The inspector explains the selected item, what it changes, and available apply or undo actions. Review the plan and restore-point option before applying changes. Some actions need administrator permission; the tour does not apply any."),
        ("2/1", "table", "Apps · installed packages", "This page lists supported installed application packages. Search and inspect the package identity before choosing to remove it; similarly named entries may serve different users or system functions."),
        ("2/1", "inspector", "Apps · removal scope", "The inspector explains the selected app and the available removal options. Removing an app can remove functionality; reinstalling may require the Store or its original installer. The walkthrough never removes a package."),
        ("2/2", "table", "Startup · what runs at sign-in", "Startup entries show programs configured to launch when you sign in, grouped by their source. Disabling startup does not uninstall the application or stop a process that is already running."),
        ("2/2", "inspector", "Startup · inspect and toggle", "Review the command, publisher and startup source before enabling or disabling an entry. Keep entries needed by your hardware or workflow. Changes occur only when you explicitly choose an action outside the tour."),
        ("2/3", "table", "Tasks · scheduled background work", "Scheduled tasks run in response to triggers or on a schedule. The grouped entries show supported tasks and current status. Read the explanation rather than disabling tasks just because they run in the background."),
        ("2/3", "inspector", "Tasks · effects and undo", "The inspector describes a task and available disable or undo controls. A disabled task no longer runs from its normal triggers. Review the tradeoffs and permission requirements before changing it."),
        ("2/4", "table", "Services · background components", "Windows services support system features and applications. This page focuses on supported optional services and their reported configuration. An idle service is not necessarily wasting meaningful resources."),
        ("2/4", "inspector", "Services · review before changing", "Read the selected service's role and consequences. Disabling a service can prevent dependent features from working. Undo controls restore supported changes; they are not a universal system backup."),
        ("3/0", "toolbar", "Event Watch · refresh and coverage", "Event Watch reads supported Windows logs in the background. The header reports coverage and access limitations. Refresh reloads events; it does not clear the Windows logs."),
        ("3/0", "table", "Live · filter and group events", "Search provider, event ID or text, filter by severity, and group repeated events. Pause stops live display updates so you can inspect a snapshot. A severity label is a clue to investigate, not a diagnosis."),
        ("3/0", "inspector", "Live · understand an event", "Select an event to see its explanation, source and available details. Event timing and repeated patterns matter. The same event ID can need context from its provider and neighboring events."),
        ("3/1", "table", "Crashes · episodes and timeline", "Crashes groups evidence around bluescreens, unexpected restarts and hardware faults. Select an episode to inspect the surrounding timeline. Events near a crash can be consequences rather than causes."),
        ("3/1", "inspector", "Crashes · evidence and dumps", "The inspector explains the selected evidence and can offer additional details or dump reading when available. A stop code or named component is a starting point for investigation, not proof of the root cause."),
        ("3/2", "table", "Summary · recurring patterns", "The summary highlights notable patterns in the loaded period and reports when nothing notable was found. Limited log access or retention can hide older events, so absence of evidence is not a complete health guarantee."),
    ];
    entries
        .into_iter()
        .map(|(p, t, h, d)| S::new(p, t, h, d))
        .collect()
}
